import { createRequire } from 'node:module';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { Chess } from 'chess.js';

// Mechanical asset packing only: keep original generated artwork, trim alpha
// margins and resample without changing aspect ratio. Never infer transparency
// from an RGB background: opaque generations must be regenerated by ImageGen.
const sharpPackage=process.argv[2];
if(!sharpPackage)throw new Error('Pass a sharp package.json path to use the existing rendering runtime.');
const sharp=createRequire(sharpPackage)('sharp');
const root=fileURLToPath(new URL('../design/porcelain-imagegen-v1/',import.meta.url));
const names=['king','queen','bishop','knight','rook','pawn'];
const symbols={k:'king',q:'queen',b:'bishop',n:'knight',r:'rook',p:'pawn'};
const heights={king:420,queen:405,bishop:386,knight:360,rook:348,pawn:325};
const manifest=[];
await mkdir(`${root}pieces`,{recursive:true});
for(const side of ['white','black'])for(const name of names){
  const filename=`${side}-${name}.png`;
  const input=await readFile(`${root}originals/${filename}`);
  const meta=await sharp(input).metadata();
  if(!meta.hasAlpha)throw new Error(`Missing alpha: ${filename}`);
  const {data,info}=await sharp(input).ensureAlpha().raw().toBuffer({resolveWithObject:true});
  let clear=0,opaque=0;
  for(let i=3;i<data.length;i+=4){if(data[i]===0)clear++;if(data[i]>200)opaque++;}
  if(clear<data.length/4*.05||opaque<100)throw new Error(`Invalid transparency or empty figure: ${filename}`);
  for(const [x,y] of [[0,0],[info.width-1,0],[0,info.height-1],[info.width-1,info.height-1]]){
    if(data[(y*info.width+x)*4+3]!==0)throw new Error(`Nontransparent corner: ${filename}`);
  }
  const trimmed=await sharp(input).trim({threshold:1}).toBuffer();
  const resized=await sharp(trimmed).resize({width:400,height:heights[name],fit:'inside',withoutEnlargement:false}).png().toBuffer();
  const size=await sharp(resized).metadata();
  const left=Math.round((512-size.width)/2),top=470-size.height;
  const sprite=await sharp({create:{width:512,height:512,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite([{input:resized,left,top}]).png().toBuffer();
  await writeFile(`${root}pieces/${filename}`,sprite);
  manifest.push({file:filename,color:side==='white'?'w':'b',role:name,width:512,height:512,visibleWidth:size.width,visibleHeight:size.height,baseline:470,alpha:true});
}
const embedded={};
for(const item of manifest)embedded[item.file]=`data:image/png;base64,${(await readFile(`${root}pieces/${item.file}`)).toString('base64')}`;
const img=(file,x,y,w)=>`<image href="${embedded[file]}" x="${x}" y="${y}" width="${w}" height="${w}"/>`;
const text=(str,x,y,size=20)=>`<text x="${x}" y="${y}" font-family="Georgia,serif" font-size="${size}" fill="#25272c">${str}</text>`;
const square=(x,y,size,dark)=>`<rect x="${x}" y="${y}" width="${size}" height="${size}" fill="${dark?'#899198':'#e9e5df'}"/>`;
const wrap=(content,w,h)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><rect width="100%" height="100%" fill="#f3f2ef"/>${content}</svg>`;
let sheet=text('Position Zero · Porcelain sprites',40,60,36)+text('ImageGen artwork / genuine alpha / square-cell sizing',40,88,16);
for(let row=0;row<2;row++)for(let i=0;i<6;i++){
  const x=40+i*228,y=116+row*230,file=`${row?'black':'white'}-${names[i]}.png`;
  sheet+=square(x,y,210,i%2)+img(file,x,y,210)+text(`${row?'Black':'Red'} ${names[i]}`,x,y+230,18);
}
sheet+=text('At playing size',40,630,26);
for(const [idx,size] of [48,64,96].entries()){
  const y=659+idx*122;
  sheet+=text(`${size} px`,40,y+size/2+6,16);
  manifest.forEach((item,i)=>{const x=150+i*size;sheet+=square(x,y,size,i%2)+img(item.file,x,y,size);});
}
await sharp(Buffer.from(wrap(sheet,1440,1040))).png().toFile(`${root}preview.png`);
let boards=text('Porcelain sprites · 64 px squares',40,50,30);
const games=[new Chess(),new Chess()];
for(const san of ['e4','e5','Nf3','Nc6','Bb5','a6','Ba4','Nf6','O-O','Be7','Re1','b5','Bb3','d6'])games[1].move(san);
games.forEach((game,i)=>{
  const bx=40+i*580,by=90;
  boards+=`<rect x="${bx-16}" y="${by-16}" width="544" height="544" fill="#25272c"/>`;
  game.board().forEach((rank,r)=>rank.forEach((piece,c)=>{
    const x=bx+c*64,y=by+r*64;
    boards+=square(x,y,64,(r+c)%2);
    if(piece)boards+=img(`${piece.color==='w'?'white':'black'}-${symbols[piece.type]}.png`,x,y,64);
  }));
  boards+=text(i?'Ruy Lopez · after 7…d6':'Initial position',bx,640,20);
});
await sharp(Buffer.from(wrap(boards,1200,680))).png().toFile(`${root}board-preview.png`);
await writeFile(`${root}manifest.json`,JSON.stringify({generator:'ImageGen',format:'PNG RGBA',canvas:512,redMapsTo:'w',baseline:470,pieces:manifest},null,2)+'\n');
console.log(`Validated and packed ${manifest.length} transparent 512px sprites; created contact sheet and legal-position previews.`);
